EXTRA.sosreceiver = () => { const s = st.viewSos; if (!s) return page(hdr('SOS', 'Family')); const mine = s.userId === me(); const host = circ() && circ().ownerId === me(); const left = Math.max(0, s.endsAt - s.serverNow); const total = (s.endsAt - s.createdAt) / 3600000; return page(hdr('SOS', 'Family') + `<div style="margin: 14px 16px 0; border-radius: 18px; padding: 18px; background: linear-gradient(145deg, #C8102E, #7A0012); color: #FFFFFF; box-shadow: 0 8px 20px rgba(200,16,46,0.3)"><div style="font-size: 12px; font-weight: 700; letter-spacing: 0.6px; text-transform: uppercase; opacity: .85">${mine ? 'Your SOS' : 'SOS from'}</div><div style="font-size: 26px; font-weight: 700">${mine ? 'is live' : esc(s.senderName)}</div><div style="font-size: 13px; opacity: .9; margin-top: 4px">${s.active ? 'Ends in ' + Math.ceil(left / 60000) + ' min' + (total >= 4 ? ' · 4 hour limit reached' : '') : 'Ended'} · ${s.location === 'none' ? 'no location shared' : s.location + ' location, ' + s.precision}</div></div>` + body((s.location !== 'none' && s.active ? `<div style="height: 160px; border-radius: 16px; background: #E8EAED; background-image: linear-gradient(#DCDFE3 1px, transparent 1px), linear-gradient(90deg, #DCDFE3 1px, transparent 1px); background-size: 48px 48px; position: relative"><span style="position: absolute; left: 50%; top: 50%; transform: translate(-50%,-50%); width: 18px; height: 18px; border-radius: 50%; background: #DA1F2D; border: 4px solid #FFFFFF; box-shadow: 0 0 0 10px rgba(218,31,45,0.18)"></span>${s.location === 'live' ? `<span style="position: absolute; left: 10px; bottom: 8px; font-size: 12px; color: #5C5C66">Trail updates every 20 s</span>` : ''}</div>` : '') + note(R.wording.sosDisclaimer) + label(mine ? 'Who has seen it' : 'Responses from the group') + (((s.responses || []).filter((r0) => !mine || r0.type === 'seen')).length ? s.responses.filter((r0) => !mine || r0.type === 'seen').map((r0) => card(`<span style="font-size: 15px">${esc(r0.name)} · ${{ seen: 'has seen this', onMyWay: 'is on their way', called: 'has called' }[r0.type]}</span>`)).join('') : card(muted(mine ? 'Nobody has seen it yet.' : 'Nobody has responded yet.'))) + (mine ? '' : muted('On my way and I called them go to the other people on this SOS, not to ' + esc(s.senderName) + '.', 12)) + (mine ? (s.active ? (total < 4 ? secondary('Extend 1 hour', 'sosextend', `data-id="${s.id}"`) : '') + primary('End my SOS', 'sosstop', `data-id="${s.id}" data-testid="sos-end"`, 'linear-gradient(145deg, #C8102E, #7A0012)', 'rgba(200,16,46,0.3)') : '') : (s.active ? primary("I've seen this", 'sosresp', `data-id="${s.id}" data-t="seen" data-testid="sos-seen"`, '#1C1C1E', 'rgba(0,0,0,0.2)') + secondary('On my way', 'sosresp', `data-id="${s.id}" data-t="onMyWay" data-testid="sos-omw"`) + secondary('I called them', 'sosresp', `data-id="${s.id}" data-t="called" data-testid="sos-called"`) + (host ? secondary('End this SOS as host', 'sosstop', `data-id="${s.id}" data-testid="sos-end-host"`) : '') : '') + muted(host ? `You host this circle, so you can end it. ${esc(s.senderName)} is told who ended it.` : `Only ${esc(s.senderName)} or the host can end this SOS.`, 12)), 10), '#F0EEF5'); };
EXTRA.sosresolved = () => { const s = st.viewSos; return page(hdr('SOS ended', 'Family') + body(card(`<span style="font-size: 16px; font-weight: 700">${s.userId === me() ? 'Your SOS' : esc(s.senderName) + "'s SOS"} ended</span>${muted(`${when(s.createdAt)} to ${s.resolvedAt ? when(s.resolvedAt) : 'expiry'}`)}`) + label('What was shared') + card(muted(s.location === 'none' ? 'No location.' : `${s.location} location, ${s.precision}. Location and trail were wiped when it ended. History keeps only the time and duration.`)) + label('Circle responses') + ((s.responses || []).length ? s.responses.map((r0) => card(`<span style="font-size: 15px">${esc(r0.name)} · ${{ seen: 'saw it', onMyWay: 'was on their way', called: 'called' }[r0.type] || r0.type}</span>`)).join('') : card(muted('Nobody acknowledged it before it ended.'))) + secondary('Back to Family', 'tab', 'data-tab="Family"'), 10), '#F0EEF5'); };
EXTRA.soshistory = () => page(hdr('Past SOS', 'Family', '', 'Last 30 days. Time and duration only, never where.') + body(((st.sosHist || []).length ? st.sosHist.map((s) => `<a href="#" data-act="viewsos" data-id="${s.id}" data-testid="hist-row" style="${CARD}; flex-direction: row; align-items: center; text-decoration: none; color: #1C1C1E"><span style="flex: 1; display: flex; flex-direction: column; gap: 2px"><span style="font-size: 15px; font-weight: 700">${esc(s.senderName)}</span>${muted(`${new Date(s.createdAt).toLocaleString()} · ${s.responses.length} responses`, 12)}</span>${chev}</a>`).join('') : card(muted('No SOS in the last 30 days.'))), 10), '#F0EEF5');
EXTRA.sharedjourney = () => { const j = st.viewJ; if (!j) return page(hdr('Journey', 'Family')); const left = Math.max(0, Math.round((j.endsAt - (j.serverNow || Date.now())) / 60000)); return page(hdr('Family journey', 'Family') + `<div style="margin: 14px 16px 0; border-radius: 18px; padding: 18px; background: linear-gradient(165deg, #2E2A9E, #1E1780 55%, #120D4F); color: #FFFFFF"><div style="font-size: 12px; font-weight: 700; letter-spacing: 0.6px; text-transform: uppercase; opacity: .8">Journey shared with you</div><div style="font-size: 26px; font-weight: 700">${esc(j.memberName)}</div><div style="font-size: 13px; opacity: .9; margin-top: 4px">${j.status === 'active' ? (j.live ? 'Sharing now · live' : 'Sharing now · an update about every 10 minutes') + ' · ' + left + ' min left' : 'Journey ended'}</div></div>` + body(`<div style="height: 200px; border-radius: 16px; background: #E8EAED; background-image: linear-gradient(#DCDFE3 1px, transparent 1px), linear-gradient(90deg, #DCDFE3 1px, transparent 1px); background-size: 48px 48px; position: relative">${j.points.map((p0, i) => `<span style="position: absolute; left: ${20 + i * 12}%; top: ${60 - i * 8}%; width: 12px; height: 12px; border-radius: 50%; background: #3D3DDF; border: 3px solid #FFFFFF"></span>`).join('')}<span style="position: absolute; left: 10px; bottom: 8px; font-size: 12px; color: #5C5C66">${j.points.length} points · ${j.live ? 'refreshes every 45 s' : 'refreshes every 10 min'}</span></div>` + muted('You see when they leave and arrive. Nobody is tracked after the journey ends.')), '#F0EEF5'); };
