EXTRA.journey = () => { const c = circ(); const j = st.journeys[0]; const snapOnly = c?.settings?.journeysSnapPointsOnly !== false; return page(hdr('Share my journey', 'Family') + body(j ? card(`<span data-testid="journey-active" style="font-size: 16px; font-weight: 700">Journey active</span>${muted(`Stops in ${Math.max(0, Math.round((j.endsAt - (j.serverNow || Date.now())) / 60000))} min. ${j.live ? 'Live sharing is on until it ends.' : 'Periodic updates: your departure, an update about every ' + R.timings.journeySnapPointMinutes + ' minutes, and your arrival.'}`)}<div style="display: flex; gap: 8px">${small('Keep sharing 1 more hour', 'jext', `data-id="${j.id}" data-testid="jext"`)}${small('Stop sharing now', 'jstop', `data-id="${j.id}" data-testid="jstop"`)}</div>`) : card(label('Who sees it') + `<div style="display: flex; flex-wrap: wrap; gap: 8px">${(c?.members || []).filter((m) => m.id !== me()).map((m) => chip(esc(m.name), (st.jRecips || []).includes(m.id), 'jrecip', `data-id="${m.id}" data-testid="jr"`, '#3D3DDF', '#EEEEFB')).join('') || muted('Everyone in the group')}</div>` + label('How long will you be?') + `<div style="display: flex; gap: 8px">${R.timings.journeyInitialMinutes.map((m) => chip(m + ' min', (st.jmin || 60) === m, 'jmin', `data-m="${m}" data-testid="jm-${m}"`)).join('')}</div>` + `<label style="display: flex; align-items: center; gap: 12px; font-size: 15px"><span style="flex: 1">Send live updates${snapOnly ? ' <span style="font-size: 12px; color: #5C5C66">(this group uses periodic updates only)</span>' : ''}</span>${toggle(!!st.jlive, 'jlivetoggle')}</label>` + muted('Periodic updates: your departure, an update about every 10 minutes, and your arrival. Up to 4 hours in total.', 12) + primary('Start sharing', 'jstart', `data-id="${c?.circleId}" data-testid="jstart"`, 'linear-gradient(135deg, #2E2A9E, #1E1780)', 'rgba(46,42,158,0.3)')) + note('A journey is seen only by the people you pick. It ends on time or when you stop it, whichever comes first.')), '#F0EEF5'); };
EXTRA.plan_cover = () => { const c = circ(); const sp = c.sponsorship; return page(hdr('Plan and cover', 'Family') + body(card(`<span data-testid="cover-status" style="font-size: 16px; font-weight: 700">${sp.live ? 'Covered by ' + R.plans[sp.tier].label : 'This group has no plan yet'}</span>${muted(sp.live ? 'Members join free. Everyone here gets Check in, Check on, SOS and Journey.' : 'Creating and joining is free. Connections need ALRT + for each person, or one plan that covers the whole group.')}`) + (sp.live ? secondary('My plans', 'loadmanage') : primary('Cover this group', 'go', 'data-s="GroupPaywall" data-testid="cover-group"', 'linear-gradient(135deg, #05603B, #17A96A)', 'rgba(10,127,79,0.3)') + secondary('Everyone uses their own ALRT +', 'selffund', 'data-testid="selffund"'))), '#F0EEF5'); };

