EXTRA.managenotes = () => { const f = st.pushSettings || {}; const F = [['awsEmergency', 'Emergency Warning (AWS)', 'Always on'], ['awsWatchAndAct', 'Watch and Act (AWS)'], ['awsAdvice', 'Advice (AWS)'], ['officialNonAws', 'Other official alerts'], ['userReported', 'Community reports']]; return page(hdr('Notifications', 'Profile', '', 'Your level sets these. Change any switch to fine-tune.') + body(label('Level') + `<div style="display: flex; flex-direction: column; gap: 8px">${R.notifications.levels.map((l) => radio(l.label, '', (st.user?.settings?.level || 'official') === l.id, 'setlevel', `data-id="${l.id}" data-testid="level-${l.id}"`)).join('')}</div>` + label('Types') + card(F.map(([k, t, n]) => `<label style="display: flex; align-items: center; gap: 12px; font-size: 15px"><span style="flex: 1">${t}${n ? `<div style="font-size: 12px; color: #5C5C66">${n}</div>` : ''}</span>${toggle(!!f[k], k === 'awsEmergency' ? 'noop' : 'pushf', `data-k="${k}" data-testid="pf-${k}" ${k === 'awsEmergency' ? 'data-locked="1"' : ''}`)}</label>`).join('')) + label('Categories') + `<div style="display: flex; flex-wrap: wrap; gap: 8px">${Object.entries(R.categories).map(([k, v]) => chip(v.name, (f.subscribedCategoryIds || []).includes(k), 'pushcat', `data-k="${k}"`, v.color, v.color + '1A')).join('')}</div>` + label('Saved places') + (st.places.length ? group('', st.places.map((p) => row(esc(p.name), `${p.radiusKm} km`, 'unsub', `data-id="${p.id}"`, '#5C5C66', small('Unsubscribe', 'unsub', `data-id="${p.id}"`)))) : card(muted('No saved places yet.'))) + secondary('Send a test notification', 'testpush', 'data-testid="testpush"'))); };
EXTRA.accessible = () => page(hdr('Accessible alerts', 'Profile', '', 'Sound, vibration and read aloud. Stays on this phone.') + body(card(`<label style="display: flex; align-items: center; gap: 12px; font-size: 15px"><span style="flex: 1">Strong vibration for urgent alerts</span>${toggle(!!st.acc?.vib, 'accvib')}</label><label style="display: flex; align-items: center; gap: 12px; font-size: 15px"><span style="flex: 1">Read urgent alerts aloud</span>${toggle(!!st.acc?.ra, 'accra')}</label>`) + secondary('Test vibration', 'toast', 'data-m="Vibration test"')));
EXTRA.points = () => { const b = st.breakdown || { byType: [] }; const pts = st.pts?.points || 0; const next = R.points.levels.find((l) => l[1] > pts); return page(hdr('Your points', 'Profile') + `<div style="margin: 14px 16px 0; border-radius: 18px; padding: 18px; background: linear-gradient(135deg, #FF6B00, #FF0004); color: #FFFFFF"><div style="font-size: 12px; font-weight: 700; letter-spacing: 0.6px; text-transform: uppercase; opacity: .85">Total points</div><div data-testid="total-points" style="font-size: 40px; font-weight: 700; line-height: 1.1">${pts}</div><div style="font-size: 13px; opacity: .9">${esc(st.pts?.level || 'Watcher')}${next ? ' · ' + (next[1] - pts) + ' to ' + next[0] : ' · top level'}</div></div>` + body(label('Where your points came from') + (b.byType.length ? card(b.byType.map((x) => `<div style="display: flex; justify-content: space-between; font-size: 15px"><span>${esc(x.type)}</span><b>${x.points > 0 ? '+' : ''}${x.points}</b></div>`).join('')) : card(muted('Nothing yet.'))) + label('How points work') + card(muted(`Report approved +${R.points.reportApproved} · Confirmed by a neighbour +${R.points.confirmedByNeighbour} · Matches an official warning +${R.points.matchesOfficial} · Guide read +${R.points.guideComplete} · Report rejected ${R.points.reportRejected}. Confirming someone else's report earns nothing. Points reward careful, accurate reports. No streaks.`, 14)) + group('', [row('Leaderboard', 'Ranks only. Names are never shown.', 'loadlb', 'data-testid="lb-open"'), row('Badges', `${(st.badges || []).length} available`, 'tab', 'data-tab="badges"')]))); };
EXTRA.leaderboard = () => { const mine = (st.lb || []).find((r0) => r0.points === (st.pts?.points || 0)); return page(hdr('Leaderboard', 'points', '', 'Completely de-identified. Ranks and points only.') + body((mine ? card(`<span style="font-size: 15px; font-weight: 700">Your position: #${mine.rank}</span>${muted('Only you can see this line.', 12)}`) : '') + group('', (st.lb || []).map((r0) => row(`#${r0.rank}`, '', 'noop', 'data-testid="lb-row"', '#5C5C66', `<b>${r0.points} pts</b>`))))); };
