EXTRA.support = () => page(hdr('Help and feedback', 'Profile') + body(`<div style="display: flex; flex-wrap: wrap; gap: 8px">${['support', 'feedback', 'question', 'other'].map((k) => chip(k[0].toUpperCase() + k.slice(1), (st.supType || 'support') === k, 'suptype', `data-k="${k}"`)).join('')}</div>` + `<textarea id="supd" data-testid="supd" placeholder="What happened?" style="height: 110px; border: 1.5px solid #E3E6EA; border-radius: 12px; padding: 12px; font: 400 14px ${FONT}; resize: none; outline: 0; box-sizing: border-box; width: 100%; background: #FFFFFF"></textarea>` + primary('Submit request', 'supsend', 'data-testid="supsend"') + (st.supSent ? card(`<span data-testid="sup-sent" style="font-size: 15px; font-weight: 700">Request submitted</span>${muted('We reply by email.')}`) : '')));
EXTRA.deleteacct = () => page(hdr('Delete your account?', 'Profile') + body(card(`<span style="font-size: 16px; font-weight: 700">Changed your mind? You have 30 days.</span>${muted('Sign in any time in the next 30 days to recover everything. After 30 days it is permanent: your reports stay anonymous, your circles lose you, and a circle you host starts a 7 day hand-over.')}`) + primary('Delete my account', 'delacct', 'data-testid="del-confirm"', 'linear-gradient(145deg, #C8102E, #7A0012)', 'rgba(200,16,46,0.3)') + ghost('Keep my account', 'tab', 'data-tab="Profile"')));
EXTRA.manage = () => { const a = st.access; const pl = a?.personal; return page(hdr('My plans', 'Profile') + body((a?.billingIssue ? note("<b>We couldn't renew ALRT +.</b> Update your payment method in your store. Your access continues for a short grace period.", '#FFF4EE', '#B84500').replace('<div', '<div data-testid="billing-issue"') : '') + label('Personal plan') + card(`<span data-testid="manage-personal" style="font-size: 16px; font-weight: 700">${pl?.plan === 'individual' ? R.plans.individual.label + (pl.isTrial ? ' trial' : '') : R.plans.free.label}</span>${muted(pl?.plan === 'individual' ? (pl.willRenew ? 'Renews ' : 'Ends ') + new Date(pl.expiresAt).toLocaleDateString() + ' · unlimited places · 10 Ask ALRT a day' : '1 saved place · 3 Ask ALRT a day')}` + (pl?.plan === 'individual' ? small('Manage in store', 'toast', 'data-m="Opens store subscription management"') : small('See ALRT +', 'paywall', 'data-ctx="me"'))) + label('Group coverage') + ((a?.groups || []).length ? group('', a.groups.map((g) => row(esc(g.name), g.sponsorship.live ? 'Covered by ' + R.plans[g.sponsorship.tier].label + (g.sponsorship.youPay ? ' · you pay' : '') : g.fundingMode === 'individual' ? 'Everyone uses their own ALRT +' : 'Not covered', 'noop', '', '#5C5C66', g.ownerId === me() && !g.sponsorship.live ? small('Cover', 'go', 'data-s="GroupPaywall"') : ''))) : card(muted('No groups yet.'))) + ((a?.unboundSponsorships || []).length ? label('Choose the group it covers') + a.unboundSponsorships.map((s) => card(`<span data-testid="unbound" style="font-size: 15px; font-weight: 700">${R.plans[s.tier].label} is paid for but not covering a group yet</span>` + (st.circles.filter((c) => c.ownerId === me()).map((c) => small(`Cover ${esc(c.name)}`, 'bind', `data-s="${s.id}" data-c="${c.circleId}" data-testid="bind-${c.circleId}"`)).join(' ') || muted('Create a group you host first.')))).join('') : '') + secondary('Restore purchases', 'restore', 'data-testid="restore"'))); };
EXTRA.guide = () => { const t = st.learnT || 'Bushfire'; const done = !!(st.user?.guides || {})[t]; return page(hdr(esc(t) + ': being prepared', 'Learn', '', `3 min · +${R.points.guideComplete} XP`) + body(card(label('Before') + muted('Know your trigger to leave. Pack a go bag now: medications, documents, chargers, water. Agree a meeting point with your people.', 15)) + card(label('During') + muted('Follow the official warning for your area word for word. Leaving early is the safest option. Do not drive through smoke.', 15)) + card(label('After') + muted('Wait for the agency to say it is safe to return. Check on neighbours. Photograph damage for insurance.', 15)) + (done ? card(`<span style="font-size: 15px; font-weight: 700; color: #15803D">Completed. Nice work staying prepared.</span>`) : primary(`Mark complete · +${R.points.guideComplete} XP`, 'guidedone', 'data-testid="guide-done"')))); };

// ---------- sheets (the Places board's sheet treatment)
function sheetWrap(inner) { return `<div data-act="close" style="position: absolute; inset: 0; background: rgba(23,23,26,0.35); z-index: 20"></div><div data-testid="sheet" style="position: absolute; left: 0; right: 0; bottom: 0; max-height: 92%; overflow: auto; background: #FFFFFF; border-radius: 24px 24px 0 0; box-shadow: 0 -8px 30px rgba(0,0,0,0.18); padding: 10px 16px 28px; box-sizing: border-box; display: flex; flex-direction: column; gap: 14px; z-index: 21; font-family: ${FONT}"><div style="align-self: center; width: 40px; height: 5px; border-radius: 3px; background: #D9D6D0"></div>${inner}</div>`; }
const sh1 = (t, sub = '') => `<div style="display: flex; flex-direction: column; gap: 4px"><h2 style="margin: 0; font-size: 22px; font-weight: 700; letter-spacing: -0.2px">${t}</h2>${sub ? muted(sub, 14) : ''}</div>`;
function sheetHtml() {
  if (!st.sheet) return ''; const f = SHEETS[st.sheet]; return f ? sheetWrap(f()) : '';
}
SHEETS.ask = () => sh1('Ask ALRT', 'Answers grounded in alerts near you') + `<div data-testid="ask-left" style="font-size: 13px; color: #5C5C66">${st.ask ? st.ask.remaining + ' of ' + st.ask.limit + ' questions left today' : ''}</div>` + input('aq', 'What does this warning mean for me?', 'data-testid="ask-input"', st.askQ || '') + primary('Ask', 'askgo', 'data-testid="ask-go"') + (st.askAns ? card(`<span data-testid="ask-answer" style="font-size: 15px; line-height: 1.5">${esc(st.askAns)}</span>${muted(st.askSrc === 'ai' ? 'AI answer, counted against today\'s questions' : st.askSrc === 'library' ? 'From the ALRT library. Not counted.' : 'Emergency number lookup. Not counted.', 12)}`) : '') + note("If you're in immediate danger, call your local emergency number now. ALRT is information, not emergency services.") + ghost('Close', 'close');
SHEETS.sos = () => { const c = circ(); const o = st.sosOpt || { loc: 0, prec: 0 }; const pv = st.sosPreview; return sh1(`Send SOS to ${esc(c?.name)}`, R.wording.sosDisclaimer) + (pv ? `<div data-testid="sos-recips" style="font-size: 13px; color: #3A3A42">Reaches ${pv.recipients.map((r0) => esc(r0.name)).join(', ') || 'nobody yet'}${pv.preset ? ' · list: ' + esc(pv.preset.name) : ''}</div>` : '') + ((st.sosLists || []).length ? `<div style="display: flex; flex-wrap: wrap; gap: 8px">${[['', 'Everyone here'], ...st.sosLists.map((l) => [l.id, l.name])].map(([id, n]) => chip(esc(n), (o.list || '') === id, 'soslist', `data-id="${id}"`, '#3D3DDF', '#EEEEFB')).join('')}</div>` : '') + label('Share location') + `<div style="display: flex; flex-wrap: wrap; gap: 8px">${R.sos.locationChoices.map((l, i) => chip(l, o.loc === i, 'sosloc', `data-i="${i}" data-testid="sosloc-${i}"`)).join('')}</div>` + (o.loc > 0 ? label('Precision') + `<div style="display: flex; gap: 8px">${R.sos.precisionChoices.map((l, i) => chip(l, o.prec === i, 'sosprec', `data-i="${i}"`)).join('')}</div>` : '') + `<div id="hold" data-testid="hold" style="position: relative; height: 84px; border-radius: 42px; background: linear-gradient(145deg, #C8102E, #7A0012); color: #FFFFFF; font: 800 17px ${FONT}; display: flex; align-items: center; justify-content: center; overflow: hidden; user-select: none; touch-action: none; box-shadow: 0 8px 20px rgba(200,16,46,0.3)"><i id="holdfill" style="position: absolute; left: 0; top: 0; bottom: 0; width: 0; background: rgba(255,255,255,0.28)"></i><span style="position: relative">Hold for 3 seconds to send</span></div>` + muted('Runs for 1 hour. You can extend it, up to 4 hours. You or the host can end it.', 12) + ghost('Cancel', 'close'); };
SHEETS.refusal = () => { const r0 = st.refusal; return sh1(r0.title) + `<div data-testid="refusal-title" style="display: none">${r0.title}</div><div data-testid="refusal-code" style="font-size: 14px; color: #3A3A42; line-height: 1.5">${r0.body}</div>` + (r0.details?.peopleCount ? note(`This group has ${r0.details.peopleCount} people.`) : '') + primary(r0.cta, 'refusalgo', 'data-testid="refusal-cta"') + ghost('Not now', 'close'); };
SHEETS.filters = () => { const f = st.filters; const cnt = (fn) => st.hazards.filter(fn).length; return sh1('Filters', 'What shows on the map and in Alerts. Emergency Warnings are never hidden.') + label('Who is speaking') + card(['aws', 'official', 'community', 'intel'].map((k) => `<label style="display: flex; align-items: center; gap: 12px; font-size: 15px">${outline(k, 24)}<span style="flex: 1">${{ aws: 'AWS warnings', official: 'Official sources', community: 'Community reports', intel: 'ALRT Assessment' }[k]}<div style="font-size: 12px; color: #5C5C66">${cnt((h) => h.source === k)} near you now</div></span>${toggle(f.sources.includes(k), 'filt', `data-k="sources" data-v="${k}" data-testid="f-${k}"`)}</label>`).join('')) + label('How serious') + card(Object.entries(R.bandWords).map(([k, [w, d]]) => `<label style="display: flex; align-items: center; gap: 12px; font-size: 15px"><span style="width: 18px; height: 18px; border-radius: 4px; background: ${R.bands[k]}; flex: none"></span><span style="flex: 1">${w}<div style="font-size: 12px; color: #5C5C66">${d}</div></span>${k === 'critical' ? pill('Always on', '#FDE8EA', '#B3141F') : toggle(f.bands.includes(k), 'filt', `data-k="bands" data-v="${k}" data-testid="b-${k}"`)}</label>`).join('')) + label('Categories') + `<div style="display: flex; flex-wrap: wrap; gap: 8px">${Object.entries(R.categories).map(([k, v]) => chip(`<span style="width: 10px; height: 10px; border-radius: 50%; background: ${v.color}"></span>${v.name}`, f.cats.includes(k), 'filt', `data-k="cats" data-v="${k}"`, v.color, v.color + '1A')).join('')}</div>` + `<div style="display: flex; gap: 10px">${secondary('Reset all', 'filtreset', 'data-testid="filt-reset"')}${primary('Show ' + visibleHazards().length + ' alerts', 'close', 'data-testid="filt-done"')}</div>`; };
const outline = (k, sz = 26) => { const c = 'fill="none" stroke="#3A3A42" stroke-width="1.8" stroke-linejoin="round"'; const m = { aws: `<path d="M12 3 22 20H2z" ${c}/>`, official: `<path d="M12 2 22 12 12 22 2 12z" ${c}/>`, community: `<circle cx="12" cy="12" r="9" ${c}/>`, global: `<rect x="3" y="3" width="18" height="18" rx="4" ${c}/>`, intel: `<path d="M12 2 4 5v6c0 5 3.4 9 8 11 4.6-2 8-6 8-11V5z" ${c}/>` }; return `<svg width="${sz}" height="${sz}" viewBox="0 0 24 24" data-outline="${k}">${m[k]}</svg>`; };
SHEETS.mapkey = () => sh1('Map key', 'Shape says who is speaking. Colour says how serious.') + label('Who is speaking') + card([['aws', 'Triangle', 'Australian Warning System. The only one that writes the level in words.'], ['official', 'Diamond', 'Other official sources. Colour for the level, never a level word.'], ['community', 'Circle', 'Community reports. Colour is the category. Always Unverified.'], ['global', 'Square', 'International feeds, shown as issued.'], ['intel', 'Shield', 'ALRT Assessment, with named sources.']].map(([k, t, d]) => `<div style="display: flex; gap: 12px; align-items: flex-start">${outline(k)}<span style="flex: 1"><b>${t}</b>${muted(d, 13)}</span></div>`).join('')) + label('AWS levels') + card(R.awsLevels.map(([t, c, d]) => `<div style="display: flex; gap: 12px; align-items: flex-start"><span style="width: 0; height: 0; border-left: 10px solid transparent; border-right: 10px solid transparent; border-bottom: 18px solid ${c}; flex: none; margin-top: 2px"></span><span style="flex: 1"><b>${t}</b>${muted(d, 13)}</span></div>`).join('')) + label('Colour') + card(`<div data-testid="severity-band" style="height: 14px; border-radius: 7px; background: linear-gradient(90deg, ${R.bands.info} 0%, ${R.bands.monitor} 38%, ${R.bands.action} 68%, ${R.bands.critical} 100%)"></div><div style="display: flex; justify-content: space-between; font-size: 12px; color: #5C5C66"><span>Less serious</span><span>More serious</span></div>` + muted('Colour shows how serious it is. The further right, the more it matters.', 13) + muted('Community circles never carry severity: their colour is the category.', 12)) + ghost('Close', 'close');
SHEETS.priming = () => sh1('Be first to know', 'Official emergency warnings, verified first.') + muted('Turn on alerts so warnings reach you even when ALRT is closed. Your phone asks once.', 14) + primary('Turn on alerts', 'primeon', 'data-testid="prime-on"') + ghost('Maybe later', 'primelater', 'data-testid="prime-later"');
SHEETS.flagblock = () => sh1('Report this alert', 'Sent to ALRT for review. The reporter is not told who flagged it.') + `<div style="display: flex; flex-wrap: wrap; gap: 8px">${['inappropriate', 'misleading', 'spam', 'harassment', 'other'].map((r0) => chip(r0[0].toUpperCase() + r0.slice(1), (st.flagReason || 'misleading') === r0, 'flagr', `data-r="${r0}"`)).join('')}</div>` + primary('Send for review', 'flag', 'data-testid="flag-send"') + secondary('Block this person', 'block', 'data-testid="block"') + ghost('Cancel', 'close');
SHEETS.sharealert = () => { const h = st.hazards.find((x) => x.id === st.detail); return sh1('Share a link', 'Public page, no sign-in needed. Community reports share at suburb precision and keep the Unverified tag.') + card(`<span style="font-size: 15px; font-weight: 700">${esc(h?.title)}</span><span data-testid="share-link" style="font-size: 13px; color: #5C5C66; word-break: break-all">https://api.safetyalrt.com/a/${h?.id}</span>`) + primary('Share', 'toast', 'data-m="Share sheet opens" data-testid="share-copy"') + secondary('Send to my family circle', 'sharefam', 'data-testid="share-fam-sheet"') + ghost('Close', 'close'); };
SHEETS.duplicate = () => { const d = st.dup; return sh1('Is this the alert?', 'A similar report is already live nearby.') + card(`<span style="font-size: 15px; font-weight: 700">${esc(d.existingTitle)}</span>${muted(esc(d.existingCategoryName))}`) + (d.canConfirm ? primary('Yes, confirm this alert', 'dupconfirm', 'data-testid="dup-confirm"') : '') + secondary('No, mine is different', 'dupforce', 'data-testid="dup-force"') + ghost('Cancel', 'close'); };
SHEETS.checkin = () => sh1('Check in', 'Tells your group you are okay. Location is only sent if you choose it.') + primary('Just check in', 'ci', 'data-mode="none" data-testid="ci-none"', 'linear-gradient(135deg, #2E2A9E, #1E1780)', 'rgba(46,42,158,0.3)') + secondary('Check in and share my location', 'ci', 'data-mode="exact" data-testid="ci-exact"') + secondary('Check in and share my suburb', 'ci', 'data-mode="suburb" data-testid="ci-suburb"') + `<div style="padding-top: 6px">${primary('I need help', 'ci', 'data-mode="help" data-testid="ci-help"', 'linear-gradient(145deg, #C8102E, #7A0012)', 'rgba(200,16,46,0.3)')}</div>` + ghost('Cancel', 'close');
SHEETS.askcheckin = () => { const c = circ(); return sh1('Ask for a check-in', 'Pick who to ask, or ask everyone.') + `<div style="display: flex; flex-wrap: wrap; gap: 8px">${c.members.filter((m) => m.id !== me()).map((m) => chip(esc(m.name), (st.askSel || []).includes(m.id), 'asksel', `data-id="${m.id}"`, '#3D3DDF', '#EEEEFB')).join('')}</div>` + input('askmsg', 'Message (optional)', '', st.askMsg || '') + primary((st.askSel || []).length ? 'Ask ' + st.askSel.length : 'Ask everyone in ' + esc(c.name), 'askgo2', 'data-testid="ask-everyone"', 'linear-gradient(135deg, #2E2A9E, #1E1780)', 'rgba(46,42,158,0.3)') + ghost('Cancel', 'close'); };
SHEETS.locrequest = () => { const lr = (st.locReqs || [])[0]; if (!lr) return sh1('Nothing pending') + ghost('Close', 'close'); return sh1(`${esc(lr.requester.name)} asked where you are`, 'Share a one-time snapshot of your location? It expires after 1 hour. Declining sends nothing.') + primary('Share once', 'locresp', `data-id="${lr.id}" data-share="1" data-testid="loc-share"`, 'linear-gradient(135deg, #2E2A9E, #1E1780)', 'rgba(46,42,158,0.3)') + secondary('Not now', 'locresp', `data-id="${lr.id}" data-share="0" data-testid="loc-decline"`); };
SHEETS.member = () => { const c = circ(); const m = c.members.find((x) => x.id === st.memberId); const host = c.ownerId === me(); return sh1(esc(m.nickname || m.name) + (c.ownerId === m.id ? ' · hosts this circle' : ''), `${m.lastCheckInAt ? 'Checked in ' + when(m.lastCheckInAt) : 'No check-in yet'} · sharing ${m.sharingLevel}`) + (m.snapshot ? card(`<span style="font-size: 15px; font-weight: 700">Last snapshot</span>${muted(`${esc(m.snapshot.label)} · ${m.snapshot.precision} · expires ${when(m.snapshot.expiresAt)}`)}`) : '') + secondary(`Ask ${esc(m.name)} to check in`, 'checkon', `data-uid="${m.id}" data-id="${c.circleId}" data-testid="md-checkon"`) + secondary('Request a one-time location', 'locreq', `data-id="${m.id}" data-testid="md-locreq"`) + (host ? secondary('Remove from circle', 'removem', `data-id="${m.id}" data-testid="md-remove"`) : '') + ghost('Close', 'close'); };
SHEETS.leave = () => sh1(`Leave ${esc(circ().name)}?`, `You keep your own alerts, map and guidance. No announcement is sent.${circ().ownerId === me() ? ' You host this circle: members get 7 days to choose a new host.' : ''}`) + primary('Leave circle', 'leave', 'data-testid="leave-go"') + ghost('Stay', 'close');
SHEETS.transfer = () => sh1('Hand the circle to') + ((st.candidates || []).length ? group('', st.candidates.map((c) => row(esc(c.name), '', 'transferto', `data-id="${c.memberId}" data-testid="cand"`))) : card(muted('Nobody else is in this circle yet.'))) + ghost('Cancel', 'close');
SHEETS.creategroup = () => sh1('Name your group', 'Creating a group is free.') + input('cn', 'Group name', 'data-testid="circle-name"', 'Nixon group') + primary('Create group', 'mkcircle', 'data-testid="make-circle"', 'linear-gradient(135deg, #2E2A9E, #1E1780)', 'rgba(46,42,158,0.3)') + ghost('Cancel', 'close');
SHEETS.joingroup = () => sh1('Join with a code', 'Joining is always free. Ask the host for their invite code or QR.') + input('jc', 'ALRT-XXXXX', 'data-testid="join-code"') + primary('Join group', 'join', 'data-testid="join"', 'linear-gradient(135deg, #2E2A9E, #1E1780)', 'rgba(46,42,158,0.3)') + secondary('Scan invite QR', 'toast', 'data-m="Camera opens to scan the QR"') + ghost('Cancel', 'close');
const _emailauth = () => sh1(st.authMode === 'login' ? 'Welcome back' : 'Create your account', 'Use at least 6 characters for the password.') + input('em', 'Email', 'data-testid="email" type="email"') + input('pw', 'Password', 'data-testid="password" type="password"') + (st.authMode === 'login' ? primary('Sign in', 'login', 'data-testid="login"') + ghost("Don't have an account? Create one", 'authmode', 'data-m="register"') + ghost('Forgot password?', 'forgotopen', 'data-testid="forgot-link"') : primary('Create account', 'register', 'data-testid="register"') + ghost('Already have an account? Sign in', 'authmode', 'data-m="login" data-testid="login-mode"')) + ghost('Cancel', 'close');
SHEETS.photo = () => sh1('Your photo', 'Shown to the people in your groups only. Never on the map, never on a report.') + `<div style="display: flex; align-items: center; gap: 14px"><span data-testid="photo-preview" style="width: 72px; height: 72px; border-radius: 50%; background: ${st.user?.photo ? `url(${st.user.photo}) center/cover` : 'linear-gradient(135deg, #FF6B00, #FF0004)'}; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 26px; flex: none">${st.user?.photo ? '' : (st.user?.name || 'S')[0].toUpperCase()}</span><label style="flex: 1">${secondary('Choose a photo', 'noop')}<input id="photofile" type="file" accept="image/*" data-testid="photo-file" style="position: absolute; width: 1px; height: 1px; opacity: 0"></label></div>` + input('pname', 'Your name', 'data-testid="pname"', st.user?.name || '') + primary('Save', 'photosave', 'data-testid="photo-save"') + (st.user?.photo ? ghost('Remove photo', 'photoremove') : '') + ghost('Close', 'close');
SHEETS.grouphoto = () => sh1('Group photo', 'Shown to members of this group only.') + `<div style="display: flex; align-items: center; gap: 14px"><span data-testid="gphoto-preview" style="width: 72px; height: 72px; border-radius: 20px; background: ${circ()?.photoUrl ? `url(${circ().photoUrl}) center/cover` : '#EEEEFB'}; flex: none"></span><label style="flex: 1">${secondary('Choose a photo', 'noop')}<input id="gphotofile" type="file" accept="image/*" data-testid="gphoto-file" style="position: absolute; width: 1px; height: 1px; opacity: 0"></label></div>` + primary('Save', 'gphotosave', 'data-testid="gphoto-save"') + ghost('Close', 'close');
SHEETS.voice = () => sh1('Speak to search', 'Recognised on this phone. Nothing is recorded or sent.') + card(`<div style="display: flex; align-items: center; gap: 12px"><span style="width: 44px; height: 44px; border-radius: 50%; background: #FFF1E8; display: flex; align-items: center; justify-content: center; flex: none"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#E8622A" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/></svg></span><span data-testid="voice-text" style="font-size: 16px; font-weight: 600">${st.voiceHeard ? esc(st.voiceHeard) : 'Listening…'}</span></div>`) + (st.voiceHeard ? primary('Search for this', 'voiceuse', 'data-testid="voice-use"') : secondary('Tap when done', 'voicedone', 'data-testid="voice-done"')) + muted('This fills the search box. Ask ALRT is a different button for questions about alerts.', 12) + ghost('Cancel', 'close');
SHEETS.addwidget = () => sh1('Add a widget to your home screen', 'Nearby alerts or your family at a glance.') + `<div style="border-radius: 22px; padding: 14px; color: #FFFFFF; background: linear-gradient(135deg, #F07E1B, #C25A00)"><b>Nearby Alerts</b><div style="font-size: 13px">The closest alerts, updated with the app</div></div><div style="border-radius: 22px; padding: 14px; color: #FFFFFF; background: linear-gradient(145deg, #2E2A9E, #120D4F)"><b>Family</b><div style="font-size: 13px">Check-ins and SOS state. Never names or places.</div></div>` + primary('Add widget', 'widgetadd') + ghost('Close', 'close');
SHEETS.sharealrt = () => sh1('Share ALRT', 'ALRT: safety alerts for where you are.') + card(muted(`A friend who installs from your link earns you ${R.points.shareInstall} points.`)) + primary('Share link', 'toast', 'data-m="Link copied"') + secondary('Show QR code', 'toast', 'data-m="QR shown"') + ghost('Close', 'close');
SHEETS.language = () => sh1('Language') + [['en', 'English'], ['es', 'Español']].map(([k, t]) => radio(t, '', (st.user?.language || 'en') === k, 'setlang', `data-k="${k}"`)).join('') + muted('Official warnings are shown in their original wording.', 12) + ghost('Close', 'close');
SHEETS.legal = () => sh1('Terms and privacy') + group('', ['Terms of Use', 'Privacy Policy', 'Emergency services disclaimer', 'Community guidelines', 'Data sources and licences'].map((t) => row(t, '', 'toast', `data-m="Opens ${t}"`))) + ghost('Close', 'close');
SHEETS.logout = () => sh1('Log out?', 'You will need to sign in again. The Family widget is cleared.') + primary('Log out', 'signout', 'data-testid="logout-go"') + ghost('Stay', 'close');
SHEETS.upgrade = () => sh1('Replace your plan?', `Your current ${R.plans[st.up?.from]?.label} on this group is replaced by ${R.plans[st.up?.to]?.label}. The old one may still renew until you cancel it in your store.`) + primary('Replace', 'upgradego', 'data-testid="upgrade-go"') + ghost('Cancel', 'close');
// voice input is not on the approved boards (hidden in V1)
const _voice = () => sh1('Speak instead of typing', 'Recognised on this phone. Nothing is recorded or sent.') + card(`<div style="text-align: center; font-size: 15px; color: #5C5C66">Listening…</div>`) + ghost('Cancel', 'close');
